"use client";

import { useInfiniteQuery, useQueryClient } from "@tanstack/react-query";
import {
  forwardRef,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { type ScrollerProps, Virtuoso } from "react-virtuoso";
import { cn } from "@/lib/utils";
import { Button } from "@/registry/zbanx/ui/button";
import { Checkbox } from "@/registry/zbanx/ui/checkbox";
import { Skeleton } from "@/registry/zbanx/ui/skeleton";
import { QueryListContext } from "./context";
import { useQueryListStore } from "./hooks";
import { createSelectionStore, type SelectionStore } from "./selection-store";
import type { QueryListFooterExtra, QueryListProps } from "./types";

export {
  useQueryListRef,
  useQueryListStore,
  useQueryListUI,
  useRowSelection,
} from "./hooks";
export { createSelectionStore, type SelectionStore } from "./selection-store";
export type {
  QueryListFetchFn,
  QueryListFooterExtra,
  QueryListFooterInfo,
  QueryListProps,
  QueryListRef,
} from "./types";

function DefaultSkeleton() {
  return (
    <div className="space-y-2 border-b border-border px-2 py-4">
      <Skeleton className="h-4 w-1/3" />
      <Skeleton className="h-3 w-full" />
      <Skeleton className="h-3 w-2/3" />
    </div>
  );
}

function SkeletonRows({
  count,
  renderSkeleton,
}: {
  count: number;
  renderSkeleton?: () => React.ReactNode;
}) {
  return (
    <>
      {Array.from({ length: count }).map((_, index) =>
        renderSkeleton ? (
          <div key={index}>{renderSkeleton()}</div>
        ) : (
          <DefaultSkeleton key={index} />
        )
      )}
    </>
  );
}

const QueryListScroller = forwardRef<HTMLDivElement, ScrollerProps>(
  function QueryListScroller(props, ref) {
    return (
      <div
        ref={ref}
        style={props.style}
        tabIndex={props.tabIndex}
        data-testid={props["data-testid"]}
        data-virtuoso-scroller={props["data-virtuoso-scroller"]}
        className="custom-scrollbar"
      >
        {props.children}
      </div>
    );
  }
);

function QueryListFooter<TItem>({
  items,
  rowKey,
  selectable,
  footerExtra,
  pageCount,
  total,
  isError,
  retry,
}: {
  items: TItem[];
  rowKey: (row: TItem) => string;
  selectable: boolean;
  footerExtra: QueryListFooterExtra | undefined;
  pageCount: number;
  total: number;
  isError: boolean;
  retry: () => void;
}) {
  const store = useQueryListStore();
  // 禁止在渲染中裸调 store 方法取数——Compiler 会把稳定对象上的纯方法调用结果跨渲染缓存，导致读到冻结值
  const [selectedIds, setSelectedIds] = useState<string[]>(() =>
    store.getSelectedIds()
  );
  useEffect(
    () => store.subscribe(() => setSelectedIds(store.getSelectedIds())),
    [store]
  );
  const loadedIds = useMemo(() => items.map(rowKey), [items, rowKey]);
  const selectedSet = useMemo(() => new Set(selectedIds), [selectedIds]);
  const selectedInList = useMemo(
    () => loadedIds.filter((id) => selectedSet.has(id)).length,
    [loadedIds, selectedSet]
  );
  const allChecked =
    loadedIds.length > 0 && selectedInList === loadedIds.length;
  const indeterminate = selectedInList > 0 && selectedInList < loadedIds.length;

  const toggleAll = useCallback(() => {
    if (allChecked) store.removeAll(loadedIds);
    else store.selectAll(loadedIds);
  }, [store, allChecked, loadedIds]);

  return (
    <div className="flex shrink-0 items-center gap-4 border-t border-[#F0F0F0] px-2 pt-2.5 text-sm">
      {selectable && (
        <>
          <label
            htmlFor="query-list-select-all"
            className="inline-flex cursor-pointer items-center gap-2"
          >
            <Checkbox
              id="query-list-select-all"
              checked={allChecked}
              indeterminate={indeterminate}
              onCheckedChange={toggleAll}
              aria-label="全选当前已加载结果"
              className="shadow-none"
            />
            全选
          </label>
          <span className="text-muted-foreground">
            已选{" "}
            <span className="font-medium text-primary">
              {selectedIds.length}
            </span>{" "}
            项
          </span>
        </>
      )}
      {footerExtra && (
        <div className="flex min-w-0 flex-1 items-center justify-end gap-3">
          {typeof footerExtra === "function"
            ? footerExtra({ pageCount, total, isError, retry })
            : footerExtra}
        </div>
      )}
    </div>
  );
}

export function QueryList<TItem, TFilters = Record<string, unknown>>(
  props: QueryListProps<TItem, TFilters>
) {
  const {
    fetchPage,
    filters,
    queryKey,
    rowKey,
    renderItem,
    renderSkeleton,
    renderEmpty,
    renderError,
    footerExtra,
    listEndText,
    pageSize = 20,
    selectable = false,
    listRef,
    onSelectionChange,
    onTotalChange,
    onError,
    onLoadingChange,
    enabled = true,
    className,
    estimatedItemHeight,
  } = props;

  const queryClient = useQueryClient();
  const [resetToken, setResetToken] = useState(0);
  const [cleared, setCleared] = useState(false);

  const filtersRef = useRef(filters);
  filtersRef.current = filters;
  const onSelectionChangeRef = useRef(onSelectionChange);
  onSelectionChangeRef.current = onSelectionChange;

  const storeRef = useRef<SelectionStore | null>(null);
  if (!storeRef.current) {
    storeRef.current = createSelectionStore((ids) =>
      onSelectionChangeRef.current?.(ids)
    );
  }
  const store = storeRef.current;

  const key = useMemo(
    () => [...queryKey, pageSize, resetToken],
    [queryKey, pageSize, resetToken]
  );
  const keyRef = useRef(key);
  keyRef.current = key;

  // biome-ignore lint/correctness/useExhaustiveDependencies: 刻意以 filters 引用变化为触发器；store 为 ref 单例稳定引用
  useEffect(() => {
    setCleared(false);
    store.clear();
  }, [filters]);

  const listQuery = useInfiniteQuery({
    queryKey: key,
    queryFn: ({ pageParam }) =>
      fetchPage({
        filters: filtersRef.current,
        page: pageParam,
        size: pageSize,
      }),
    initialPageParam: 1,
    getNextPageParam: (lastPage, allPages) => {
      const attempted = allPages.length * pageSize;
      return attempted < lastPage.total ? allPages.length + 1 : undefined;
    },
    enabled: enabled && !cleared,
    retry: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
  });
  const queryRef = useRef(listQuery);
  queryRef.current = listQuery;

  const loading = listQuery.isFetching || (listQuery.isPending && !cleared);
  useEffect(() => {
    onLoadingChange?.(loading);
  }, [onLoadingChange, loading]);

  useEffect(() => {
    if (listQuery.error) onError?.(listQuery.error);
  }, [onError, listQuery.error]);

  const refetchCurrent = useCallback(() => {
    void queryRef.current.refetch({ cancelRefetch: false });
  }, []);

  const reload = useCallback(() => {
    setCleared(false);
    refetchCurrent();
  }, [refetchCurrent]);

  const reloadToFirstPage = useCallback(() => {
    setCleared(false);
    setResetToken((token) => token + 1);
  }, []);

  const clear = useCallback(() => {
    setCleared(true);
    store.clear();
    void queryClient.removeQueries({ queryKey: keyRef.current });
  }, [queryClient, store]);

  const rowsRef = useRef(new Map<string, TItem>());

  if (listRef) {
    listRef.reload = (options) => {
      if (options?.toFirstPage) reloadToFirstPage();
      else reload();
    };
    listRef.clear = clear;
    listRef.getSelectedIds = () => store.getSelectedIds();
    listRef.getSelectedRows = () => {
      const rows: TItem[] = [];
      for (const id of store.getSelectedIds()) {
        const row = rowsRef.current.get(id);
        if (row) rows.push(row);
      }
      return rows;
    };
    listRef.clearSelection = () => store.clear();
  }

  const pages = listQuery.data?.pages ?? [];
  const items = useMemo(() => pages.flatMap((page) => page.items), [pages]);
  const total = pages[0]?.total ?? 0;
  useEffect(() => {
    onTotalChange?.(total);
  }, [onTotalChange, total]);
  useEffect(() => {
    const map = new Map<string, TItem>();
    for (const item of items) map.set(rowKey(item), item);
    rowsRef.current = map;
  }, [items, rowKey]);

  const retry = refetchCurrent;

  // 防同 tick 双触发（isFetchingNextPage 是异步状态，同 tick 内读到的是 stale 值）
  const inflightRef = useRef(false);
  // 仅认 false→true 跳变，杜绝慢网速下贴底不动连环取数
  const atTopRef = useRef(true);
  const atBottomRef = useRef(false);

  const tryFetchNext = useCallback(() => {
    const query = queryRef.current;
    if (
      inflightRef.current ||
      query.isFetchingNextPage ||
      !query.hasNextPage ||
      query.error
    )
      return;
    inflightRef.current = true;
    void query.fetchNextPage({ cancelRefetch: false }).finally(() => {
      inflightRef.current = false;
    });
  }, []);

  const handleAtTopChange = useCallback((atTop: boolean) => {
    atTopRef.current = atTop;
  }, []);

  const handleAtBottomChange = useCallback(
    (atBottom: boolean) => {
      const wasAtBottom = atBottomRef.current;
      atBottomRef.current = atBottom;
      if (atBottom && !wasAtBottom) tryFetchNext();
    },
    [tryFetchNext]
  );

  // biome-ignore lint/correctness/useExhaustiveDependencies: 刻意以 items.length 变化为触发器
  useEffect(() => {
    if (atTopRef.current && atBottomRef.current) tryFetchNext();
  }, [items.length, tryFetchNext]);

  // biome-ignore lint/correctness/useExhaustiveDependencies: 刻意以 key 引用变化为触发器
  useEffect(() => {
    atTopRef.current = true;
    atBottomRef.current = false;
  }, [key]);

  const contextValue = useMemo(
    () => ({ store, selectable }),
    [store, selectable]
  );

  const error = listQuery.error instanceof Error ? listQuery.error : null;
  const showSkeleton = listQuery.isPending && items.length === 0 && !cleared;
  const showError = error != null && items.length === 0;

  return (
    <QueryListContext.Provider value={contextValue}>
      <div className={cn("flex h-full min-h-0 flex-col", className)}>
        <div className="min-h-0 flex-1">
          {showSkeleton ? (
            <SkeletonRows count={4} renderSkeleton={renderSkeleton} />
          ) : showError ? (
            (renderError?.(error, retry) ?? (
              <div className="flex h-full flex-col items-center justify-center gap-3 py-10">
                <p className="text-muted-foreground text-sm">
                  加载失败，请稍后重试。
                </p>
                <Button variant="outline" size="sm" onClick={retry}>
                  重试
                </Button>
              </div>
            ))
          ) : items.length === 0 ? (
            (renderEmpty?.() ?? (
              <p className="py-10 text-center text-muted-foreground text-sm">
                暂无数据
              </p>
            ))
          ) : (
            <Virtuoso
              className="h-full rounded-lg"
              data={items}
              defaultItemHeight={estimatedItemHeight}
              atTopStateChange={handleAtTopChange}
              atBottomStateChange={handleAtBottomChange}
              itemContent={(index, row) => renderItem(row, index)}
              components={{
                Scroller: QueryListScroller,
                Footer: () => (
                  <div>
                    {listQuery.isFetchingNextPage && (
                      <SkeletonRows count={2} renderSkeleton={renderSkeleton} />
                    )}
                    {!listQuery.hasNextPage && listEndText}
                  </div>
                ),
              }}
            />
          )}
        </div>
        {(selectable || footerExtra) && items.length > 0 && (
          <QueryListFooter
            items={items}
            rowKey={rowKey}
            selectable={selectable}
            footerExtra={footerExtra}
            pageCount={pages.length}
            total={total}
            isError={listQuery.isError}
            retry={retry}
          />
        )}
      </div>
    </QueryListContext.Provider>
  );
}

export default QueryList;

import type { ReactNode } from "react";

/** 单页抓取函数：filters 由调用方受控传入，返回追加式页面 */
export type QueryListFetchFn<TItem, TFilters> = (params: {
  filters: TFilters;
  page: number;
  size: number;
}) => Promise<{ items: TItem[]; total: number }>;

/**
 * 列表命令式句柄（非受控读取）。
 * 通过 useQueryListRef() 创建后经 listRef 传入，父组件可直接调用。
 */
export interface QueryListRef<TItem> {
  /** 重新加载：默认重验已加载页；toFirstPage 则丢弃已加载页回到第一页 */
  reload: (options?: { toFirstPage?: boolean }) => void;
  /** 清空数据并暂停拉取，直到 filters 变化或 reload */
  clear: () => void;
  /** 获取选中 id（非受控读取，批量操作入口） */
  getSelectedIds: () => string[];
  /** 获取选中行数据 */
  getSelectedRows: () => TItem[];
  /** 清空选中 */
  clearSelection: () => void;
}

/** 底部栏右侧扩展信息（分页信息等） */
export interface QueryListFooterInfo {
  /** 已加载页数 */
  pageCount: number;
  /** 服务端总数 */
  total: number;
  /** 当前是否有查询错误 */
  isError: boolean;
  /** 重试 */
  retry: () => void;
}

/** 底部栏右侧扩展：静态节点或接收分页信息的渲染函数 */
export type QueryListFooterExtra =
  | ReactNode
  | ((info: QueryListFooterInfo) => ReactNode);

export interface QueryListProps<TItem, TFilters> {
  /** 单页抓取函数（调用方注入，组件内执行） */
  fetchPage: QueryListFetchFn<TItem, TFilters>;
  /** 受控筛选值（抽屉/chips 等域 UI 在外，筛选归调用方所有） */
  filters: TFilters;
  /** TanStack queryKey（调用方计算，如需忽略快照等展示态由调用方处理） */
  queryKey: unknown[];
  /** 行 key 提取 */
  rowKey: (row: TItem) => string;
  /** 行渲染（行内选中态经 useRowSelection 自取，无需传参） */
  renderItem: (row: TItem, index: number) => ReactNode;
  /** 加载骨架（初筛与翻页共用，内部 UI 态经 useQueryListUI 自取） */
  renderSkeleton?: () => ReactNode;
  /** 空数据渲染 */
  renderEmpty?: () => ReactNode;
  /** 错误渲染（带重试回调） */
  renderError?: (error: Error, retry: () => void) => ReactNode;
  /** 底部栏右侧扩展（分页信息等） */
  footerExtra?: QueryListFooterExtra;
  /** 全部加载完成后的尾部提示 */
  listEndText?: ReactNode;
  /** 每页条数 */
  pageSize?: number;
  /** 是否开启行多选 */
  selectable?: boolean;
  /** 命令式句柄 */
  listRef?: QueryListRef<TItem>;
  /** 选中变化通知（仅通知，不接管状态） */
  onSelectionChange?: (ids: string[]) => void;
  /** 服务端总数变化通知（供外部标题等展示） */
  onTotalChange?: (total: number) => void;
  /** 查询失败通知（诊断日志等，组件内不消费） */
  onError?: (error: unknown) => void;
  /** 加载态变化通知（拉取中，或尚无数据且未清空的待加载态） */
  onLoadingChange?: (loading: boolean) => void;
  /** 查询总开关（如筛选恢复完成前禁用） */
  enabled?: boolean;
  /** 虚拟列表行高预估（透传 Virtuoso defaultItemHeight，不传则自动测量） */
  estimatedItemHeight?: number;
  className?: string;
}

"use client";

import { useCallback, useContext, useRef, useSyncExternalStore } from "react";
import { QueryListContext } from "./context";
import type { QueryListRef } from "./types";

/** 创建稳定的命令式句柄对象（noop 默认，方法在 render 体赋值） */
export function useQueryListRef<TItem>(): QueryListRef<TItem> {
  return useRef<QueryListRef<TItem>>({
    reload: () => {},
    clear: () => {},
    getSelectedIds: () => [],
    getSelectedRows: () => [],
    clearSelection: () => {},
  }).current;
}

function useQueryListContextValue() {
  const context = useContext(QueryListContext);
  if (!context) throw new Error("必须在 QueryList 内使用");
  return context;
}

/** 读取列表内部存储（同包内底部栏等使用） */
export function useQueryListStore() {
  return useQueryListContextValue().store;
}

/** 行级选中订阅：快照为单个 boolean，仅本行变化才重渲染 */
export function useRowSelection(id: string): {
  selected: boolean;
  toggle: (next: boolean) => void;
} {
  const store = useQueryListStore();
  const getSnapshot = useCallback(() => store.has(id), [store, id]);
  const selected = useSyncExternalStore(
    store.subscribe,
    getSnapshot,
    getSnapshot
  );
  const toggle = useCallback(
    (next: boolean) => store.toggle(id, next),
    [store, id]
  );
  return { selected, toggle };
}

/** 行样式开关订阅（骨架与行同源，如 selectable 让位与占位） */
export function useQueryListUI(): { selectable: boolean } {
  const context = useContext(QueryListContext);
  if (!context) throw new Error("必须在 QueryList 内使用");
  return { selectable: context.selectable };
}

"use client";

import { createContext } from "react";
import type { SelectionStore } from "./selection-store";

export interface QueryListContextValue {
  store: SelectionStore;
  selectable: boolean;
}

/** 列表内部上下文：选中存储与行样式开关单源，行与骨架同源消费，杜绝两者漂移 */
export const QueryListContext = createContext<QueryListContextValue | null>(
  null
);

/**
 * 选中存储（框架无关纯逻辑，可跨项目复用）。
 * useSyncExternalStore 订阅，行级以单个 boolean 快照细粒度更新。
 */

export interface SelectionStore {
  subscribe: (listener: () => void) => () => void;
  getVersion: () => number;
  has: (id: string) => boolean;
  getSelectedIds: () => string[];
  /** 切换单个选中态（next 缺省时取反） */
  toggle: (id: string, next?: boolean) => void;
  /** 并入一批 id（全选用） */
  selectAll: (ids: string[]) => void;
  /** 剔除一批 id（全不选用，保留批次之外的选中） */
  removeAll: (ids: string[]) => void;
  clear: () => void;
  /** 落在给定集合中的选中数（全选/半选派生用） */
  countIn: (ids: string[]) => number;
}

export function createSelectionStore(
  onChange?: (ids: string[]) => void
): SelectionStore {
  let selected = new Set<string>();
  let version = 0;
  const listeners = new Set<() => void>();

  const emit = () => {
    version += 1;
    for (const listener of [...listeners]) listener();
    onChange?.([...selected]);
  };

  return {
    subscribe: (listener: () => void) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    getVersion: () => version,
    has: (id: string) => selected.has(id),
    getSelectedIds: () => [...selected],
    toggle: (id: string, next = !selected.has(id)) => {
      if (next === selected.has(id)) return;
      const copy = new Set(selected);
      if (next) copy.add(id);
      else copy.delete(id);
      selected = copy;
      emit();
    },
    selectAll: (ids: string[]) => {
      const copy = new Set(selected);
      let changed = false;
      for (const id of ids) {
        if (!copy.has(id)) {
          copy.add(id);
          changed = true;
        }
      }
      if (!changed) return;
      selected = copy;
      emit();
    },
    removeAll: (ids: string[]) => {
      if (ids.length === 0) return;
      const doomed = new Set(ids);
      let changed = false;
      const copy = new Set<string>();
      for (const id of selected) {
        if (doomed.has(id)) changed = true;
        else copy.add(id);
      }
      if (!changed) return;
      selected = copy;
      emit();
    },
    clear: () => {
      if (selected.size === 0) return;
      selected = new Set();
      emit();
    },
    countIn: (ids: string[]) => {
      let count = 0;
      for (const id of ids) {
        if (selected.has(id)) count += 1;
      }
      return count;
    },
  };
}
